API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(aws_api_gateway_http_apis, "AWS API Gateway (HTTP APIs)", "AWS API Gateway", "Edge routing, schema validation, and rate limiting within budget, handling inbound payment authorizations.")
    Component(aws_waf, "AWS WAF", "AWS WAF", "Inspects inbound traffic for threats and provides edge protection against DDoS and injection attacks.")
    Component(edge_tokenizer_lambda_component, "Edge Tokenizer Lambda Component", "AWS Lambda (Go)", "High-performance edge tokenization for inbound payloads.")
}

Rel(aws_api_gateway_http_apis, aws_waf, "Inspects inbound traffic for threats", "AWS WAF Integration")
Rel(aws_api_gateway_http_apis, edge_tokenizer_lambda_component, "Processes and tokenizes inbound payment authorizations")
@enduml

Case Management.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(case_management, "Case Management") {
    Component(Analyst_SPA, "Analyst SPA", "React hosted in S3 and served via Amazon CloudFront", "Lightweight frontend SPA for rapid analyst workflows.")
    Component(API_Router_Auth_Component, "API Router & Auth Component", "Express.js", "Manages cases, submits overrides, and injects secrets at startup.")
    Component(Case_Workflow_Engine_with_Prioritization_Queue, "Case Workflow Engine with Prioritization Queue", "Node.js", "Processes state transitions and prioritizes queues.")
    Component(Audit_Logger_Component_with_AWS_KMS_integration, "Audit Logger Component with AWS KMS integration", "Node.js", "Triggers audit events for analyst actions and generates cryptographic signatures.")
}

Rel(Analyst_SPA, API_Router_Auth_Component, "Manages cases and submits overrides", "HTTPS/REST with OAuth2/OIDC JWT")
Rel(API_Router_Auth_Component, Case_Workflow_Engine_with_Prioritization_Queue, "Processes state transitions and prioritizes queues", "In-memory function calls")
Rel(Case_Workflow_Engine_with_Prioritization_Queue, Audit_Logger_Component_with_AWS_KMS_integration, "Triggers audit events for analyst actions", "In-memory function calls")

@enduml

Async Messaging.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Async Messaging container

Container_Boundary(async_messaging, "Async Messaging") {
    Component(SQS_FIFO_Queue, "SQS FIFO Queue", "Amazon SQS FIFO", "High-throughput message queue with message group IDs for ordered, exactly-once audit event processing.")
    Component(Dead_Letter_Queue, "Dead-Letter Queue", "Amazon SQS DLQ", "Captures unprocessable messages for failure analysis and isolation.")
    Component(VPC_Interface_Endpoint, "VPC Interface Endpoint", "AWS VPC Interface Endpoint", "Secures internal communication with the messaging service.")
}

Rel(SQS_FIFO_Queue, Dead_Letter_Queue, "Forwards failed messages")
Rel(VPC_Interface_Endpoint, SQS_FIFO_Queue, "Routes private network traffic")
@enduml
